class LRUCache:
    """
    A class that implements an LRU (Least Recently Used) Cache using a hashmap for 
    O(1) access to cache items and a simple list to maintain the order of usage.
    Elements in the list are managed to reflect the most recently used items.
    """

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.order = []

    def get(self, key: int) -> int:
        """Return the value of the key if exists, otherwise return -1."""
        if key in self.cache:
            self.order.remove(key)
            self.order.append(key)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        """Add a key-value pair to the cache."""
        if key in self.cache:
            self.cache[key] = value
            self.order.remove(key)
            self.order.append(key)
        else:
            if len(self.cache) >= self.capacity:
                lru_key = self.order.pop(0)
                del self.cache[lru_key]
            self.cache[key] = value
            self.order.append(key)

class LRUCache:
    """
    A class that implements an LRU (Least Recently Used) Cache using a hashmap for
    O(1) access and a list to track usage order based on access frequency. A custom 
    mechanism prevents using indices directly for moving items to the top.
    """

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.usage = []

    def get(self, key: int) -> int:
        """Return the value of the key if exists, otherwise return -1."""
        if key in self.cache:
            self.usage.remove(key)
            self.usage.insert(0, key)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        """Add a key-value pair to the cache."""
        if key in self.cache:
            self.cache[key] = value
            self.usage.remove(key)
            self.usage.insert(0, key)
        else:
            if len(self.cache) >= self.capacity:
                lru_key = self.usage.pop()
                del self.cache[lru_key]
            self.cache[key] = value
            self.usage.insert(0, key)
